#define FMT_HEADER_ONLY
#define main si_original_cli_main
#include "../si-cuda/src/main.cu"
#undef main
#include <cassert>
#include <set>
#include <dlfcn.h>
const float SI_GUARD=-1234567.0f;
struct Segments{double seconds=0;std::chrono::steady_clock::time_point begin;void resume(){begin=std::chrono::steady_clock::now();}void pause(){seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count();}};
void cb(cublasStatus_t e){if(e!=CUBLAS_STATUS_SUCCESS){fprintf(stderr,"cuBLASstatus%d\n",int(e));exit(3);}}
struct StudyCase{Dataset*d;unsigned P,U;bool repaired;std::vector<tile>tiles;std::vector<std::set<unsigned>>sets;std::vector<float>oracle;StudyCase(std::string name,unsigned part,bool fix):repaired(fix){d=readDataset(name);d->universe++;U=d->universe;P=std::min(part,d->cardinality);d->offsets=new unsigned[d->cardinality];thrust::exclusive_scan(d->sizes,d->sizes+d->cardinality,d->offsets,0);tiles=splitToTiles(d->cardinality,P);sets.resize(d->cardinality);for(unsigned i=0;i<d->cardinality;i++)for(size_t j=d->offsets[i];j<d->offsets[i]+d->sizes[i];j++)sets[i].insert(d->elements[j]);for(unsigned i=0;i<tiles.size();i++)for(unsigned j=i;j<tiles.size();j++){auto&A=tiles[i];auto&B=tiles[j];std::vector<float>x(P*P,0);for(unsigned a=0;a<A.length;a++)for(unsigned b=0;b<B.length;b++){unsigned count=0;for(auto e:sets[A.start+a])count+=sets[B.start+b].count(e);x[a*P+b]=float(count);}oracle.insert(oracle.end(),x.begin(),x.end());oracle.insert(oracle.end(),17,SI_GUARD);}}};
struct Captured{std::vector<float>input,out;double seconds;bool correct;};
Captured execute(StudyCase&c){size_t N=size_t(c.U)*c.P,M=size_t(c.P)*c.P;std::vector<float>A(N,0),B(N,0),counts(c.tiles.size()*(c.tiles.size()+1)/2*M),ga(17,SI_GUARD),gb(17);Captured cap;cap.correct=true;float *a,*b,*out;cublasHandle_t handle;Segments timer;errorCheck(cudaDeviceSynchronize());timer.resume();errorCheck(cudaMalloc((void**)&a,(N+17)*4));errorCheck(cudaMalloc((void**)&b,(N+17)*4));errorCheck(cudaMalloc((void**)&out,(M+17)*4));cb(cublasCreate_v2(&handle));timer.pause();errorCheck(cudaMemcpy(a+N,ga.data(),68,cudaMemcpyHostToDevice));errorCheck(cudaMemcpy(b+N,ga.data(),68,cudaMemcpyHostToDevice));errorCheck(cudaMemcpy(out+M,ga.data(),68,cudaMemcpyHostToDevice));errorCheck(cudaDeviceSynchronize());timer.resume();float alpha=1,beta=0;size_t run=0;
for(unsigned i=0;i<c.tiles.size();i++){auto&ta=c.tiles[i];populateBinaryMatrix(A.data(),c.d,ta.start,ta.end);errorCheck(cudaMemcpy(a,A.data(),N*4,cudaMemcpyHostToDevice));errorCheck(cudaDeviceSynchronize());timer.pause();std::vector<float>actual(N+17);errorCheck(cudaMemcpy(actual.data(),a,(N+17)*4,cudaMemcpyDeviceToHost));cap.correct=cap.correct&&std::equal(A.begin(),A.end(),actual.begin())&&std::equal(ga.begin(),ga.end(),actual.begin()+N);cap.input.insert(cap.input.end(),actual.begin(),actual.end());timer.resume();
for(unsigned j=i;j<c.tiles.size();j++){auto&tb=c.tiles[j];populateBinaryTransposeMatrix(B.data(),c.d,c.P,tb.start,tb.end);errorCheck(cudaMemcpy(b,B.data(),N*4,cudaMemcpyHostToDevice));errorCheck(cudaDeviceSynchronize());timer.pause();errorCheck(cudaMemcpy(actual.data(),b,(N+17)*4,cudaMemcpyDeviceToHost));cap.correct=cap.correct&&std::equal(B.begin(),B.end(),actual.begin())&&std::equal(ga.begin(),ga.end(),actual.begin()+N);cap.input.insert(cap.input.end(),actual.begin(),actual.end());timer.resume();if(c.repaired){errorCheck(cudaMemset(out,0,M*4));}cb(cublasSgemm(handle,CUBLAS_OP_N,CUBLAS_OP_N,tb.length,ta.length,c.U,&alpha,b,c.repaired?c.P:tb.length,a,c.U,&beta,out,c.repaired?c.P:tb.length));errorCheck(cudaMemcpy(counts.data()+run*M,out,M*4,cudaMemcpyDeviceToHost));errorCheck(cudaDeviceSynchronize());timer.pause();errorCheck(cudaMemcpy(gb.data(),out+M,68,cudaMemcpyDeviceToHost));cap.out.insert(cap.out.end(),counts.begin()+run*M,counts.begin()+(run+1)*M);cap.out.insert(cap.out.end(),gb.begin(),gb.end());run++;timer.resume();memset(B.data(),0,N*4);}memset(A.data(),0,N*4);}
errorCheck(cudaFree(a));errorCheck(cudaFree(b));errorCheck(cudaFree(out));cb(cublasDestroy_v2(handle));errorCheck(cudaDeviceSynchronize());timer.pause();cap.seconds=timer.seconds;cap.correct=cap.correct&&cap.out==c.oracle;return cap;}
int main(int argc,char**argv){assert(argc==4);unsigned P=std::stoul(argv[2]);StudyCase c(argv[1],P,std::stoi(argv[3])!=0);auto warm=execute(c);assert(warm.correct);cublasHandle_t probe;cb(cublasCreate_v2(&probe));int version;cb(cublasGetVersion_v2(probe,&version));cublasMath_t mode;cb(cublasGetMathMode(probe,&mode));cublasPointerMode_t pointer;cb(cublasGetPointerMode_v2(probe,&pointer));cb(cublasDestroy_v2(probe));Dl_info info{};dladdr((void*)&cublasSgemm_v2,&info);printf("STUDY_SOFTWARE {\"cublas_version\":%d,\"math_mode\":%d,\"pointer_mode\":%d,\"cublas_path\":\"%s\",\"authored_GPU_kernel_definitions\":0}\n",version,int(mode),int(pointer),info.dli_fname?info.dli_fname:"unknown");for(int trial=1;trial<=5;trial++){auto x=execute(c);std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)x.input.data(),x.input.size()*4);f.write((char*)x.out.data(),x.out.size()*4);f.close();assert(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":null,\"max_rel_error\":null,\"timing_region\":\"sum_source_alloc_handle_hostpacking_completed_H2D_SGEMM_completed_D2H_hostclear_free_destroy_segments_excluding_actualinput_guard_readbacks\",\"timing_valid\":true,\"jit_excluded\":true,\"input_prefix_count\":%zu,\"authored_GPU_kernel_definitions\":0,\"source_timing_instrumented_segments\":true,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu}}\n",trial,x.seconds,x.correct?"true":"false",x.out.size(),x.input.size(),path.c_str(),x.input.size()+x.out.size());fflush(stdout);if(!x.correct)return 1;}return 0;}
